// FUNCTION: BFME2 0x001974D0 size=344 name=?Build_Active_Pivot_Map@HAnimComboDataClass@@QAEXXZ evidence=N:ledger tier=B hypothesis:Z
void HAnimComboDataClass::Build_Active_Pivot_Map()
{
	// One weight per pivot of the animation: 1 where the animation moves the pivot, 0 elsewhere.
	if (PivotMap != 0) PivotMap->Release_Ref();
	if (HAnim == 0) {
		PivotMap = 0;
		return;
	}

	int pivots = HAnim->Get_Num_Pivots();
	PivotMap = new PivotMapClass;
	PivotMap->Resize(pivots);
	for (int pivot = 0; pivot < pivots; pivot++) {
		if (HAnim->Is_Node_Motion_Present(pivot)) {
			PivotMap->Add(1.0f);
		} else {
			PivotMap->Add(0.0f);
		}
	}
}

