void HAnimComboClass::Reset(void)
{
	int numAnimations = HAnimComboData.Count();
	while (numAnimations--) {
		HAnimComboDataClass *data = HAnimComboData[numAnimations];
		if (data && (!data->Shared)) {
			delete data;
		}
	}
	HAnimComboData.Reset_Active();
}


